package dev.pocketengine.features.local.project;

import static org.junit.Assert.*;
import dev.pocketengine.features.EngineModule;
import java.nio.charset.StandardCharsets;
import java.util.LinkedHashMap;
import java.util.Map;
import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;

public final class ProjectLiveEditPolicyTest {
    private static final String PROJECT="11111111-1111-4111-8111-111111111111",CHECKOUT="22222222-2222-4222-8222-222222222222";
    private static JSONObject snapshot(Map<String,String> files)throws Exception {JSONArray values=new JSONArray();for(var file:files.entrySet())values.put(new JSONObject().put("path",file.getKey()).put("content",file.getValue()));return new JSONObject().put("checkout",new JSONObject().put("id",CHECKOUT).put("projectId",PROJECT)).put("files",values);}
    private static Map<String,String> source(){Map<String,String> files=new LinkedHashMap<>();files.put("package.json","{\"type\":\"module\",\"devDependencies\":{\"vite\":\"8.3.5\"}}");files.put("package-lock.json","{\"lockfileVersion\":3}");files.put("tools/dev.mjs","import { createServer } from 'vite';\n");files.put("src/main.js","export const total = 40;\n");files.put("src/style.css","body { color: black; }\n");return files;}
    @Test public void policyPinsActualExistingPathsAndAllOtherLaunchInputs()throws Exception {
        JSONObject source=snapshot(source()),policy=ProjectLiveEditPolicy.create(source,new JSONArray().put("src/main.js").put("src/style.css"));ProjectLiveEditPolicy.requireStartup(policy,source);assertTrue(policy.getBoolean("subsequentSourceExecution"));assertFalse(policy.getBoolean("createsFiles"));assertEquals("same_original_host_run",policy.getString("lifetime"));assertEquals(2,policy.getJSONArray("editableFiles").length());
        JSONObject described=ProjectSources.describe(source);ProjectLiveEditPolicy.requireLaunchManifest(policy,described.getJSONArray("files"),PROJECT,CHECKOUT,described.getString("sourceDigest"));
        JSONObject forged=ProjectSources.copy(policy).put("accepted",true);assertThrows(SecurityException.class,()->ProjectLiveEditPolicy.verified(forged));
    }
    @Test public void mutableRevisionIsSeparateFromImmutableStartupAndStillRequiresCurrentSha()throws Exception {
        Map<String,String> files=source();JSONObject before=snapshot(files),policy=ProjectLiveEditPolicy.create(before,new JSONArray().put("src/main.js"));String hash=ProjectSources.sha256(files.get("src/main.js").getBytes(StandardCharsets.UTF_8));ProjectLiveEditPolicy.requireEdit(policy,before,"src/main.js",hash,"export const total = 45;\n");files.put("src/main.js","export const total = 45;\n");JSONObject after=snapshot(files);ProjectLiveEditPolicy.requireCurrent(policy,after);assertNotEquals(policy.getString("initialSourceDigest"),ProjectSources.describe(after).getString("sourceDigest"));assertThrows(SecurityException.class,()->ProjectLiveEditPolicy.requireStartup(policy,after));assertThrows(SecurityException.class,()->ProjectLiveEditPolicy.requireEdit(policy,after,"src/main.js",hash,"stale write"));
    }
    @Test public void locksToolsConfigurationAndForeignInputsCannotBorrowLivePolicy()throws Exception {
        for(String changed:new String[]{"package.json","package-lock.json","tools/dev.mjs"}){Map<String,String> files=source();JSONObject policy=ProjectLiveEditPolicy.create(snapshot(files),new JSONArray().put("src/main.js"));files.put(changed,files.get(changed)+"\nchanged");assertThrows(changed,SecurityException.class,()->ProjectLiveEditPolicy.requireCurrent(policy,snapshot(files)));}
        for(String path:new String[]{".env","src/../main.js","tools/main.js","scripts/main.js","node_modules/pkg/index.js","package.json","package-lock.json","src/tsconfig.json","src/vite.config.js",".pocketworld/dev.json"})assertFalse(path,ProjectLiveEditPolicy.allowedPath(path));
    }
    @Test public void policyDoesNotPermitCreatingRemovingOrEditingUnlistedFiles()throws Exception {
        Map<String,String> files=source();JSONObject before=snapshot(files),policy=ProjectLiveEditPolicy.create(before,new JSONArray().put("src/main.js"));assertThrows(IllegalArgumentException.class,()->ProjectLiveEditPolicy.create(before,new JSONArray().put("src/new.js")));assertThrows(SecurityException.class,()->ProjectLiveEditPolicy.requireEdit(policy,before,"src/style.css",ProjectSources.sha256(files.get("src/style.css").getBytes(StandardCharsets.UTF_8)),"body{}"));files.remove("src/main.js");assertThrows(SecurityException.class,()->ProjectLiveEditPolicy.requireCurrent(policy,snapshot(files)));
        Map<String,String> extra=source();extra.put("src/new.js","export const newSource=1");assertThrows(SecurityException.class,()->ProjectLiveEditPolicy.requireCurrent(policy,snapshot(extra)));
    }
    @Test public void nulInvalidUtf8OversizeAndDuplicateMembersAreNotSourceAuthority()throws Exception {
        JSONObject before=snapshot(source());assertThrows(IllegalArgumentException.class,()->ProjectLiveEditPolicy.create(before,new JSONArray().put("src/main.js").put("src/main.js")));JSONObject policy=ProjectLiveEditPolicy.create(before,new JSONArray().put("src/main.js"));String hash=policy.getJSONArray("editableFiles").getJSONObject(0).getString("initialSha256");assertThrows(IllegalArgumentException.class,()->ProjectLiveEditPolicy.requireEdit(policy,before,"src/main.js",hash,"bad\0source"));assertThrows(IllegalArgumentException.class,()->ProjectLiveEditPolicy.requireEdit(policy,before,"src/main.js",hash,"x".repeat(ProjectLiveEditPolicy.MAX_EDIT_BYTES+1)));assertThrows(java.nio.charset.CharacterCodingException.class,()->ProjectLiveEditPolicy.requireEdit(policy,before,"src/main.js",hash,"\ud800"));
    }
    @Test public void sourceAndProjectIdentityAreNotRecoverableFromPolicyJsonAlone()throws Exception {
        JSONObject before=snapshot(source()),policy=ProjectLiveEditPolicy.create(before,new JSONArray().put("src/main.js")),foreign=ProjectSources.copy(before);foreign.getJSONObject("checkout").put("id","33333333-3333-4333-8333-333333333333");assertThrows(SecurityException.class,()->ProjectLiveEditPolicy.requireCurrent(policy,foreign));JSONObject changed=ProjectSources.copy(policy);changed.getJSONArray("editableFiles").getJSONObject(0).put("path","tools/dev.mjs");assertThrows(SecurityException.class,()->ProjectLiveEditPolicy.verified(changed));
    }
    @Test public void formalViteTemplateUsesOfficialLockedDependencyAndRealHmrApis()throws Exception {
        Map<String,String> files=template();JSONObject pkg=new JSONObject(files.get("package.json")),lock=new JSONObject(files.get("package-lock.json"));assertEquals("8.3.5",pkg.getJSONObject("devDependencies").getString("vite"));assertFalse(pkg.getJSONObject("devDependencies").has("esbuild"));JSONObject packages=lock.getJSONObject("packages");var names=packages.keys();while(names.hasNext()){String name=names.next();JSONObject value=packages.getJSONObject(name);if(!name.isEmpty()){assertTrue(name,value.getString("resolved").startsWith("https://registry.npmjs.org/"));assertTrue(name,value.getString("integrity").startsWith("sha512-"));}}
        assertTrue(files.get("tools/dev.mjs").contains("configFile: false, envDir: false"));assertTrue(files.get("tools/dev.mjs").contains("strictPort: true"));assertTrue(files.get("src/main.js").contains("import.meta.hot.dispose"));assertTrue(files.get("src/main.js").contains("listeners.abort()"));assertTrue(files.get("src/main.js").contains("import.meta.hot.accept()"));assertTrue(files.get("index.html").contains("id=\"budget\""));assertTrue(files.get("index.html").contains("id=\"cost\""));
    }
    @Test public void managedPlanRequiresExplicitDevWatchPathsAndNeverMarksNativeStartAsReadiness()throws Exception {
        Fixture local=new Fixture();JSONObject plan=ProjectBuildPlan.create(local,local.request().put("devWatch",true).put("liveEditPaths",new JSONArray().put("src/main.js").put("src/budget.js"))),step=ProjectBuildPlan.step(plan,"run"),payload=step.getJSONObject("payload");assertEquals("project.runtime.run",step.getString("localCommand"));assertEquals("owned_service",payload.getString("runMode"));assertEquals("node",payload.getString("executable"));assertEquals("[\"tools/dev.mjs\"]",payload.getJSONArray("argv").toString());assertEquals(300000,payload.getInt("timeoutMillis"));assertFalse(payload.has("ready"));assertTrue(payload.getBoolean("devWatch"));assertEquals(2,payload.getJSONArray("liveEditPaths").length());dev.pocketengine.features.plugins.PluginRules.validateArguments(new JSONObject().put("plan",ProjectBuildPlan.verified(plan)).put("stepId","run"),new JSONObject().put("type","object").put("properties",new JSONObject().put("plan",new JSONObject().put("type","object")).put("stepId",new JSONObject().put("type","string"))).put("additionalProperties",false));JSONObject changed=ProjectDevelopment.exact(plan,step);changed.getJSONObject("payload").getJSONArray("liveEditInitialSha256").put(0,"f".repeat(64));assertThrows(SecurityException.class,()->ProjectLiveEditPolicy.fromExact(changed));ProjectLiveEditPolicy.requireStartup(ProjectLiveEditPolicy.fromExact(ProjectDevelopment.exact(plan,step)),local.source);
        assertThrows(IllegalArgumentException.class,()->ProjectBuildPlan.create(local,local.request().put("devWatch",true).put("liveEditPaths",new JSONArray().put("tools/dev.mjs"))));assertThrows(IllegalArgumentException.class,()->ProjectBuildPlan.create(local,local.request().put("devWatch",true).put("runMode","foreground").put("liveEditPaths",new JSONArray().put("src/main.js"))));
    }
    private static Map<String,String> template()throws Exception {Map<String,String> result=new LinkedHashMap<>();JSONArray files=ProjectTemplates.files("web-live");for(int i=0;i<files.length();i++)result.put(files.getJSONObject(i).getString("path"),files.getJSONObject(i).getString("content"));return result;}
    private static final class Fixture implements EngineModule {
        final JSONObject source=ProjectLiveEditPolicyTest.snapshot(template());Fixture()throws Exception{}
        JSONObject request()throws Exception{return new JSONObject().put("checkoutId",CHECKOUT).put("runtimeId","managed_process_v1").put("intent","run").put("runMode","owned_service").put("ecosystem","node").put("expectedSourceDigest",ProjectSources.describe(source).getString("sourceDigest"));}
        public String id(){return "local";}public JSONObject snapshot(){return new JSONObject();}public JSONObject handle(String command,JSONObject input)throws Exception {return switch(command){case "export"->ProjectSources.copy(source);case "probe"->new JSONObject().put("termux",new JSONObject());case "listJobs"->new JSONObject().put("termuxJobs",new JSONArray());case "project.runtime.describe"->new JSONObject().put("identity","a".repeat(64)).put("canExecute",true).put("tools",new JSONArray().put(new JSONObject().put("name","node").put("hashVerified",true)));default->throw new AssertionError(command);};}
    }
}
